import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CdjpmwdR.js";const g=JSON.parse('{"title":"Agile and Lean in Software Development: A Practitioner’s View","description":"A practice-driven framing of Agile and Lean overlaps in software teams—goals, methods, and organizational evolution—with a focus on executable practices.","frontmatter":{"category":"domain","date":"2023-12-01","title":"Agile and Lean in Software Development: A Practitioner’s View","description":"A practice-driven framing of Agile and Lean overlaps in software teams—goals, methods, and organizational evolution—with a focus on executable practices.","tags":["domain","productivity","automation","lean"],"image":"https://pic2.zhimg.com/v2-1bdb1be25c8713045f24a89090ee8be9_r.jpg"},"headers":[],"relativePath":"en/blogs/2023/202312-agile-and-lean.md","filePath":"en/blogs/2023/202312-agile-and-lean.md"}'),r={name:"en/blogs/2023/202312-agile-and-lean.md"};function n(l,e,s,c,d,m){return t(),i("div",null,[...e[0]||(e[0]=[o('<p><em>(This article is based on hands‑on experience. It does not try to cover every theoretical branch – only what’s executable.)</em></p><h2 id="agile-and-lean" tabindex="-1">Agile and Lean <a class="header-anchor" href="#agile-and-lean" aria-label="Permalink to &quot;Agile and Lean&quot;">​</a></h2><p><strong>Agile</strong> (development) started from the Agile Manifesto. It summarizes iterative, incremental ways of building software to respond to change and improve quality.</p><p><strong>Lean</strong> (production) grew out of the Toyota Production System (TPS): creating more value with less work.</p><p>The origins are different, but their values and goals overlap heavily.</p><p>Questions I keep coming back to:</p><ul><li>Is software development a <strong>creative</strong> activity, or a <strong>manufacturing</strong> activity?</li><li>How is software delivery similar to / different from industrial product delivery?</li><li>How close can a software pipeline get to a factory assembly line?</li></ul><p>While tracing the roots of Scrum, Kanban and other &quot;agile project management&quot; methods, you quickly see their manufacturing DNA. Today most software looks like an industrial product:</p><ul><li>Clear design artifacts (architecture diagrams)</li><li>Clear processes (frameworks, languages)</li><li>Clear workers (engineers)</li><li>Clear steps (dev, deploy, operate)</li></ul><p>At the same time software is also <strong>exploratory</strong>:</p><ul><li>Highly cross‑domain</li><li>Cheap materials (code)</li><li>Big leverage from individual experts</li></ul><p>So we need both:</p><ul><li>Borrow manufacturing flow and discipline</li><li>Preserve the exploratory nature of software products</li></ul><h2 id="tech-management-×-theory-practice" tabindex="-1">Tech / Management × Theory / Practice <a class="header-anchor" href="#tech-management-×-theory-practice" aria-label="Permalink to &quot;Tech / Management × Theory / Practice&quot;">​</a></h2><p><img src="https://pic1.zhimg.com/v2-123e5739332a6ba55f85609d172cac94_r.jpg" alt=""></p><p>A few observations:</p><ul><li>In a broad sense, &quot;Agile&quot; includes XP, Clean Code, DevOps, etc.</li><li>Scrum and Kanban both have strong roots in Toyota. They later migrated into software and were branded as agile management methods. (Ken Schwaber is both an Agile Manifesto author and one of the creators of modern Scrum.)</li><li>Applying <strong>lean value stream</strong> analysis to software pushed automation and tooling across the pipeline to reduce handoff time and context switching.</li><li>The <strong>lean value tree</strong> can focus product vision and investment and help define a real MVP.</li></ul><h2 id="individual-team-department-company" tabindex="-1">Individual, Team, Department, Company <a class="header-anchor" href="#individual-team-department-company" aria-label="Permalink to &quot;Individual, Team, Department, Company&quot;">​</a></h2><p><img src="https://pic2.zhimg.com/v2-1bdb1be25c8713045f24a89090ee8be9_r.jpg" alt=""></p><p>From an org perspective:</p><ul><li>Early on, Agile focused more on <strong>individual practice</strong> (there were simply fewer programmers): TDD, pair programming, etc.</li><li>As teams and systems grew, and cognitive load increased: <ul><li>We introduced project management for larger teams: Scrum, Kanban</li><li>We reduced cognitive load: DDD, platformization, modularization</li><li>We upgraded tooling: DevOps, automation, cloud‑native</li></ul></li><li>For IT‑centric companies, &quot;product&quot; is software, so org structure shifts too: <ul><li>Flatter hierarchies</li><li>Coaching over mentoring; emphasis on self‑learning</li><li>Self‑managing teams, organized by product / value stream rather than rigid horizontal departments</li></ul></li></ul><p>Agile and Lean are not magic words. They are two lenses to see the same thing:</p><blockquote><p>How do we <strong>turn ideas into running software</strong> with less waste and more learning?</p></blockquote><p>For that, I care less about what a team calls its process, and more about:</p><ul><li>Is there a clear value chain from customer to code to customer again?</li><li>Are we making small, reversible bets instead of big, irreversible ones?</li><li>Are feedback loops short enough – from prod back to the team?</li><li>Is the org structure helping or fighting these loops?</li></ul>',25)])])}const u=a(r,[["render",n]]);export{g as __pageData,u as default};
